 color: #495057;
 margin-bottom: 15px;
 font-size: 1.3rem;
 border-left: 4px solid #0073e6;
 padding-left: 15px;
}

.support-description {
 color: #6c757d;
 margin-bottom: 20px;
 line-height: 1.6;
}

